class Solution {
  public int minimumK(int[] nums) {
    int lo = 1, hi = 100000;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      long operations = 0;
      for (int x : nums) operations += (x + mid - 1) / mid;
      if (operations <= (long) mid * mid) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }
}
